import React, { useState, useEffect } from "react";
import { collection, getDocs, addDoc, updateDoc, deleteDoc, doc } from "firebase/firestore";
import { getAuth, signOut } from "firebase/auth";
import { useNavigate } from "react-router-dom";
import { db } from "../firebase/firebaseConfig";
import "./EmployeeList.css"; 

interface Employee {
  id: string;
  firstName: string;
  lastName: string;
  dob: string;
  department: string;
  position: string;
  salary: number | string;
  doj: string;
  employmentType: string;
}

const EmployeeList: React.FC = () => {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [editEmployee, setEditEmployee] = useState<Employee | null>(null);
  const [newData, setNewData] = useState<Partial<Employee>>({});
  const navigate = useNavigate();
  const auth = getAuth();

  useEffect(() => {
    const fetchEmployees = async () => {
      const querySnapshot = await getDocs(collection(db, "employees"));
      const employeeList: Employee[] = querySnapshot.docs.map((doc) => ({
        id: doc.id,
        ...doc.data(),
      })) as Employee[];
      setEmployees(employeeList);
    };

    fetchEmployees();
  }, []);

  // Delete Employee
  const handleDelete = async (id: string) => {
    await deleteDoc(doc(db, "employees", id));
    setEmployees(employees.filter(emp => emp.id !== id));
  };

  // Edit Employee
  const handleEdit = (employee: Employee) => {
    setEditEmployee(employee);
    setNewData(employee); // Pre-fill form with existing data
  };

  // Save Edited Employee
  const handleSave = async () => {
    if (editEmployee) {
      const employeeRef = doc(db, "employees", editEmployee.id);
      await updateDoc(employeeRef, newData);
      setEmployees(employees.map(emp => (emp.id === editEmployee.id ? { ...emp, ...newData } : emp)));
      setEditEmployee(null);
    }
  };

  // Logout Function
  const handleLogout = async () => {
    await signOut(auth);
    navigate("/login");
  };

  return (
    <div className="employee-container">
      <h2>People</h2>
      <button className="add-employee-btn">+ Add New Employee</button>

      <table className="employee-table">
        <thead>
          <tr>
            <th>Name</th>
            <th>D.O.E</th>
            <th>Employment Type</th>
            <th>Department</th>
            <th>Role</th>
            <th>Salary</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {employees.map((employee) => (
            <tr key={employee.id}>
              <td>{employee.firstName} {employee.lastName}</td>
              <td>{employee.doj}</td>
              <td>{employee.employmentType}</td>
              <td>{employee.department}</td>
              <td>{employee.position}</td>
              <td>€{employee.salary}</td>
              <td>
                <button className="edit-btn" onClick={() => handleEdit(employee)}>✏️</button>
                <button className="delete-btn" onClick={() => handleDelete(employee.id)}>🗑️</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* Edit Employee Modal */}
      {editEmployee && (
        <div className="edit-modal">
          <h3>Edit Employee</h3>
          <input type="text" value={newData.firstName || ""} onChange={(e) => setNewData({...newData, firstName: e.target.value})} />
          <input type="text" value={newData.lastName || ""} onChange={(e) => setNewData({...newData, lastName: e.target.value})} />
          <input type="text" value={newData.department || ""} onChange={(e) => setNewData({...newData, department: e.target.value})} />
          <input type="text" value={newData.position || ""} onChange={(e) => setNewData({...newData, position: e.target.value})} />
          <input type="number" value={newData.salary || ""} onChange={(e) => setNewData({...newData, salary: e.target.value})} />
          <button onClick={handleSave}>Save</button>
          <button onClick={() => setEditEmployee(null)}>Cancel</button>
        </div>
      )}

      {/* Logout Button */}
      <button className="logout-btn" onClick={handleLogout}>Logout</button>
    </div>
  );
};

export default EmployeeList;
